const windowStartIso = (sec: number): string => {
    return new Date(sec * 1000).toISOString();
};

const fireMartingaleMail = (fn: () => Promise<void>): void => {
    void fn().catch((e) =>
        Logger.warning(`[马丁邮件] 发送失败: ${e instanceof Error ? e.message : String(e)}`)
    );
};

// Generated By AI Start (Cursor)
const martingaleSideLabelMatchesLeading = (sideLabel: string, leading: string): boolean => {
    return sideLabel.trim().toLowerCase() === leading.trim().toLowerCase();
};

/**
 * 在输出「待收盘」日志且能解析两侧价时：趋势跟单下若押边与偏高侧不一致则发邮件（每挂单窗去重）。
 */
const maybeFireTrendMismatchAlertOnPendingLog = (
    cfg: MartingaleRuntimeConfig,
    seriesK: string,
    ob: NonNullable<MartingaleSeriesPersisted['openBet']>,
    trendTr: MartingaleBinaryTrend,
    trendHintLine: string
): void => {
    if (!cfg.emailOnTrendMismatch || cfg.entrySideMode !== 'trend_follow') {
        return;
    }
    const dedupeKey = `${seriesK}|${ob.slug}|${ob.windowStartSec}`;
    const lead = leadingOutcomeLabelFromResolvedTrend(trendTr);
    if (lead == null) {
        trendMismatchMailSentKeys.delete(dedupeKey);
        return;
    }
    if (martingaleSideLabelMatchesLeading(ob.sideLabel, lead)) {
        trendMismatchMailSentKeys.delete(dedupeKey);
        return;
    }
    if (trendMismatchMailSentKeys.has(dedupeKey)) {
        return;
    }
    trendMismatchMailSentKeys.add(dedupeKey);
    fireMartingaleMail(() =>
        notifyMartingaleTrendSideMismatch(
            {
                seriesKey: seriesK,
                sideLabel: ob.sideLabel,
                leadingLabel: lead,
                trendHintLine: trendHintLine,
                slug: ob.slug,
                stakeUsd: ob.stakeUsd,
            },
            cfg.emailOnTrendMismatch
        )
    );
};
